use spore_core::{creature_skin_queue_v1::Queue,creature_skin_cube_walk_v1 as cube,native_sse::{self,Policy,SseError}};use std::io::Write;
fn main(){let origin=[-2.;3];let mut q=Queue::from_seed(0x020203,256,8193,1024).unwrap();let mut log=Vec::new();let n=q.run(&cube::tables(),&cube::face_records(),origin,1.,0.01,0.001,Policy::Mxcsr1f80,256,|p|{let v=native_sse::scoped(Policy::Mxcsr1f80,||Ok::<_,SseError>(1.5-((p[0]*p[0]+p[1]*p[1])+p[2]*p[2]))).unwrap();log.push([p[0].to_bits(),p[1].to_bits(),p[2].to_bits(),v.to_bits()]);v}).unwrap();assert_eq!(n,q.entries.len());assert!(n<=256&&q.geometry.corner_count<=1024&&q.geometry.position_count<=1024&&q.triangles.len()<=1024&&log.len()<=8192);let mut out=Vec::new();for v in [q.cursor as u32,q.entries.len() as u32,q.geometry.status,q.geometry.corner_count,q.geometry.position_count as u32,q.triangles.len() as u32,log.len() as u32]{out.extend(v.to_le_bytes())}for i in 0..256{let e=q.entries.get(i).copied().unwrap_or_default();for v in [e.packed|((e.faces as u32)<<24),e.known as u32|((e.class as u32)<<8)]{out.extend(v.to_le_bytes())}}for i in 0..0x4000{out.extend(q.keys[i].to_le_bytes());out.extend(q.indices[i].to_le_bytes())}for r in q.geometry.records.iter().take(1024){for v in r{out.extend(v.to_le_bytes())}}for i in 0..0x8000{for v in [q.geometry.corner_keys[i],q.geometry.corner_values[i][0],q.geometry.corner_values[i][1]]{out.extend(v.to_le_bytes())}}for i in 0..0x8000{for v in [q.geometry.edge_keys[i][0],q.geometry.edge_keys[i][1],q.geometry.edge_values[i]]{out.extend(v.to_le_bytes())}}for p in &q.geometry.positions{for v in p{out.extend(v.to_bits().to_le_bytes())}}for c in &q.geometry.counts{for v in c{out.extend(v.to_le_bytes())}}for i in 0..1024{for v in q.triangles.get(i).copied().unwrap_or([0;3]){out.extend(v.to_le_bytes())}}for i in 0..8192{for v in log.get(i).copied().unwrap_or([0;4]){out.extend(v.to_le_bytes())}}std::io::stdout().write_all(&out).unwrap();}
